def existing_shares(apps, schema_editor):
    """The founding partners keep exactly what they had: each wallet gets the old
    shared percent, the pool for shareholders becomes three times that (30% by
    default), and closed days record what was shared out."""
    from decimal import Decimal
    Settings = apps.get_model('revenue', 'RevenueSettings')
    Wallet = apps.get_model('revenue', 'ShareWallet')
    Day = apps.get_model('revenue', 'RevenueDay')
    cfg = Settings.objects.filter(pk=1).first()
    pct = cfg.share_percent if cfg else Decimal('10.00')
    if cfg:
        cfg.partner_pool_percent = min(pct * 3, Decimal('100.00'))
        cfg.save(update_fields=['partner_pool_percent'])
    Wallet.objects.filter(slot__in=(1, 2, 3)).update(percent=pct)
    for day in Day.objects.all():
        day.shared = day.base - day.pool
        day.save(update_fields=['shared'])


